actions.script:
activeOrgId=null
if(!ec.user.isInGroup('ADMIN')){ec.user.context.activeOrgId=null;ec.user.context.userOrgIds=[];ec.user.context.filterOrgIds=[]}
def pref=ec.user.getPreference('ACTIVE_ORGANIZATION')
if(!pref || pref=='_NA_') return
if(ec.user.isInGroup('ADMIN')) {activeOrgId=pref;return}
ec.user.context.activeOrgId=null;ec.user.context.userOrgIds=[];ec.user.context.filterOrgIds=[]
def partyId=ec.user.userAccount?.partyId
if(!partyId) return
def info=ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo').parameters([partyId:partyId]).disableAuthz().call()
if(ec.message.hasError())return
def ids=info?.userOrgIds ?: []
activeOrgId=ids.contains(pref) && info?.activeOrgId==pref ? pref : null
ec.user.context.activeOrgId=activeOrgId;ec.user.context.userOrgIds=ids;ec.user.context.filterOrgIds=activeOrgId ? [activeOrgId] : []

def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call(); def org=scope.activeOrgId

allowed=false
def types=[product:['mantle.product.Product','productId','ownerPartyId'],barcode:['zenith.erp.barcode.ProductBarcode','barcodeId','organizationPartyId'],label:['zenith.erp.barcode.BarcodeLabel','labelId','organizationPartyId'],job:['zenith.erp.barcode.BarcodePrintJob','printJobId','organizationPartyId']]
def type=types[kind]
if(!type || !recordId){ec.message.addError('Select an existing barcode record.');return}
def row=ec.entity.find(type[0]).condition(type[1],recordId).disableAuthz().one()
if(!row || (!ec.user.isInGroup('ADMIN') && (!org || !row[type[2]] || row[type[2]]!=org))){ec.message.addError('You do not have access to this barcode record.');return}
if(write){
 def permission=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:'barcode']).disableAuthz().call()
 if(!permission.canWrite){ec.message.addError('Barcode write access is required.');return}
}
record=row;allowed=true

valid=false;value=(barcodeValue ?: '').toString().trim()
def types=['BctEan13','BctEan8','BctUpcA','BctUpcE','BctCode128','BctCode39','BctQrCode','BctInternal']
def checkDigit={String v -> int sum=0;for(int i=v.length()-2,j=0;i>=0;i--,j++)sum+=Character.getNumericValue(v.charAt(i))*(j%2==0?3:1);((10-sum%10)%10)==Character.getNumericValue(v.charAt(v.length()-1))}
def error=null
if(!types.contains(barcodeTypeEnumId))error='Choose a supported barcode type.'
else if(!value || value.length()>2048 || value.indexOf(0)>=0)error='Enter a barcode value of at most 2048 characters.'
else if(barcodeTypeEnumId in ['BctEan13','BctEan8','BctUpcA']){
 int length=[BctEan13:13,BctEan8:8,BctUpcA:12][barcodeTypeEnumId]
 if(!(value==~ /[0-9]+/) || value.length()!=length || !checkDigit(value))error='Enter the required digits with a valid EAN/UPC check digit.'
}else if(barcodeTypeEnumId=='BctUpcE'){
 if(!(value==~ /[01][0-9]{7}/))error='UPC-E requires eight digits including number system 0 or 1 and a check digit.'
 else {
  def d=value.substring(1,7); def last=d[5];def expanded
  if(last in ['0','1','2'])expanded=value[0]+d.substring(0,2)+last+'0000'+d.substring(2,5)+value[7]
  else if(last=='3')expanded=value[0]+d.substring(0,3)+'00000'+d.substring(3,5)+value[7]
  else if(last=='4')expanded=value[0]+d.substring(0,4)+'00000'+d[4]+value[7]
  else expanded=value[0]+d.substring(0,5)+'0000'+last+value[7]
  if(!checkDigit(expanded))error='UPC-E check digit is invalid.'
 }
}else if(barcodeTypeEnumId=='BctCode39' && !(value==~ /[0-9A-Z .\$\/+%\-]+/))error='Code 39 accepts uppercase letters, digits, spaces and - . $ / + %.'
else if(barcodeTypeEnumId=='BctQrCode' && (!java.nio.charset.StandardCharsets.UTF_8.newEncoder().canEncode(value) || value.getBytes('UTF-8').length>2048))error='QR requires valid Unicode text of at most 2048 UTF-8 bytes.'
else if(barcodeTypeEnumId in ['BctCode128','BctInternal'] && (!(value==~ /[ -~]+/) || value.length()>256))error='Code 128/Internal requires 1–256 printable ASCII characters.'
if(error){ec.message.addError(error);return};valid=true

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'product',recordId:productId,write:true]).call(); if(!access.allowed) return; def record=access.record

if(!record.ownerPartyId){ec.message.addError('Select an organization-owned product.');return}
def owner=record.ownerPartyId
// Serialize organization-wide code/GTIN reservations before the product-primary lock.
ec.entity.find('mantle.party.Party').condition('partyId',owner).forUpdate(true).disableAuthz().one()
ec.entity.find('mantle.product.Product').condition('productId',productId).forUpdate(true).one()
def checked=ec.service.sync().name('zenith.barcode.BarcodeServices.validate#BarcodeValue').parameters([barcodeTypeEnumId:barcodeTypeEnumId,barcodeValue:barcodeValue]).call()
if(!checked.valid)return
barcodeValue=checked.value;isPrimary=isPrimary ?: 'N'
if(!(isPrimary in ['Y','N'])){ec.message.addError('Choose Yes or No for Primary.');return}
def aliases=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:barcodeValue]).call().aliases
def collision=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',owner).condition('barcodeValue','in',aliases).disableAuthz().count()
def pseudoCollision=ec.entity.find('mantle.product.Product').condition('ownerPartyId',owner).condition('pseudoId','in',aliases).condition('productId','not-equals',productId).disableAuthz().count()
def idCollision=ec.entity.find('mantle.product.Product').condition('ownerPartyId',owner).condition('productId','in',aliases).condition('productId','not-equals',productId).disableAuthz().count()
if(collision || pseudoCollision || idCollision){ec.message.addError('This barcode is already assigned in this organization.');return}
if(!record.pseudoId && !ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',productId).condition('organizationPartyId',owner).condition('isPrimary','Y').count())isPrimary='Y'
if(isPrimary=='Y')ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',productId).condition('organizationPartyId',owner).condition('isPrimary','Y').list().each{ec.service.sync().name('update#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:it.barcodeId,isPrimary:'N']).call()}
def result=ec.service.sync().name('create#zenith.erp.barcode.ProductBarcode').parameters([productId:productId,organizationPartyId:owner,barcodeTypeEnumId:barcodeTypeEnumId,barcodeValue:barcodeValue,isPrimary:isPrimary,isActive:'Y']).call()
barcodeId=result?.barcodeId
if(isPrimary=='Y' && !ec.message.hasError())ec.service.sync().name('update#mantle.product.Product').parameters([productId:productId,pseudoId:barcodeValue]).call()

def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call(); def org=scope.activeOrgId

def prd=ec.entity.find('mantle.product.Product').condition('productId',productId).disableAuthz().one()
if(!prd || !prd.ownerPartyId || (!ec.user.isInGroup('ADMIN') && (!org || prd.ownerPartyId!=org))){ec.message.addError('You do not have access to this product.');return}
def writable=['barcode','pos','inventory'].any {module -> ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:module]).call().canWrite }
if(!writable){ec.message.addError('Product code write access is required.');return}

ec.entity.find('mantle.party.Party').condition('partyId',prd.ownerPartyId).forUpdate(true).disableAuthz().one()
ec.entity.find('mantle.product.Product').condition('productId',productId).forUpdate(true).disableAuthz().one()

def code=barcodeValue?.trim()
if(!code || prd.pseudoId==code)return
def aliases=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:code]).call().aliases
if(ec.entity.find('mantle.product.Product').condition('ownerPartyId',prd.ownerPartyId).condition('pseudoId','in',aliases).condition('productId','not-equals',productId).disableAuthz().count() || ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',prd.ownerPartyId).condition('barcodeValue','in',aliases).condition('productId','not-equals',productId).disableAuthz().count()){ec.message.addError('This code belongs to another product.');return}
ec.service.sync().name('update#mantle.product.Product').parameters([productId:productId,pseudoId:code]).call()

def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call(); def org=scope.activeOrgId

def prd=ec.entity.find('mantle.product.Product').condition('productId',productId).disableAuthz().one()
if(!prd || !prd.ownerPartyId || (!ec.user.isInGroup('ADMIN') && (!org || prd.ownerPartyId!=org))){ec.message.addError('You do not have access to this product.');return}
def writable=['barcode','pos','inventory'].any {module -> ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:module]).call().canWrite }
if(!writable){ec.message.addError('Product code write access is required.');return}

ec.entity.find('mantle.party.Party').condition('partyId',prd.ownerPartyId).forUpdate(true).disableAuthz().one()
ec.entity.find('mantle.product.Product').condition('productId',productId).forUpdate(true).disableAuthz().one()

def value=code?.trim()
if(!value)return // Clearing pseudoId does not delete independently assigned secondary barcodes.
if(ec.entity.find('mantle.product.Product').condition('ownerPartyId',prd.ownerPartyId).condition('productId',value).condition('productId','not-equals',productId).disableAuthz().count()){ec.message.addError('This code matches another product ID.');return}
def aliases=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:value]).call().aliases
if(ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',prd.ownerPartyId).condition('barcodeValue','in',aliases).condition('productId','not-equals',productId).disableAuthz().count() || ec.entity.find('mantle.product.Product').condition('ownerPartyId',prd.ownerPartyId).condition('pseudoId','in',aliases).condition('productId','not-equals',productId).disableAuthz().count()){ec.message.addError('This code belongs to another product barcode.');return}
ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',productId).condition('organizationPartyId',prd.ownerPartyId).condition('isPrimary','Y').list().each {if(it.barcodeValue!=value)ec.service.sync().name('update#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:it.barcodeId,isPrimary:'N']).call()}
def mine=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',prd.ownerPartyId).condition('productId',productId).condition('barcodeValue',value).one()
if(mine)ec.service.sync().name('update#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:mine.barcodeId,isPrimary:'Y',isActive:'Y']).call()
else ec.service.sync().name('create#zenith.erp.barcode.ProductBarcode').parameters([productId:productId,organizationPartyId:prd.ownerPartyId,barcodeValue:value,barcodeTypeEnumId:'BctInternal',isPrimary:'Y',isActive:'Y']).call()

def org=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId
def product=ec.entity.find('mantle.product.Product').condition('productId',productId).disableAuthz().one()
if(!product || !product.ownerPartyId || (!ec.user.isInGroup('ADMIN') && (!org || product.ownerPartyId!=org))){ec.message.addError('You do not have access to this product.');return}
def writable=['barcode','pos','inventory'].any {module -> ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:module]).disableAuthz().call().canWrite}
if(!writable){ec.message.addError('Product code write access is required.');return}
ec.entity.find('mantle.party.Party').condition('partyId',product.ownerPartyId).forUpdate(true).disableAuthz().one()
ec.entity.find('mantle.product.Product').condition('productId',productId).forUpdate(true).one()
def primary=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',productId).condition('organizationPartyId',product.ownerPartyId).condition('isPrimary','Y').list()
if(primary.any{it.organizationPartyId!=product.ownerPartyId}){ec.message.addError('Barcode ownership is inconsistent.');return}
primary.each{it.delete()}
def next=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',productId).condition('organizationPartyId',product.ownerPartyId).condition('isActive','Y').orderBy('barcodeId').list()
code=next ? next[0].barcodeValue : ''
if(next)ec.service.sync().name('update#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:next[0].barcodeId,isPrimary:'Y']).call()
ec.service.sync().name('update#mantle.product.Product').parameters([productId:productId,pseudoId:code ?: null]).call()

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'product',recordId:productId,write:true]).call(); if(!access.allowed) return; def record=access.record

def pre=prefix ?: 'ZEN'
if(!(pre==~ /[A-Z0-9-]{1,20}/)){ec.message.addError('Use 1–20 uppercase letters, digits or hyphens for the prefix.');return}
def rng=new java.security.SecureRandom();def owner=record.ownerPartyId
for(int attempt=0;attempt<20;attempt++){
 def value=pre+String.format('%09d',rng.nextInt(1000000000))
 if(!ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',owner).condition('barcodeValue',value).disableAuthz().count() && !ec.entity.find('mantle.product.Product').condition('ownerPartyId',owner).condition('pseudoId',value).disableAuthz().count()){barcodeValue=value;break}
}
if(!barcodeValue){ec.message.addError('Could not allocate a unique barcode. Please retry.');return}
def result=ec.service.sync().name('zenith.barcode.BarcodeServices.add#ProductBarcode').parameters([productId:productId,barcodeTypeEnumId:'BctInternal',barcodeValue:barcodeValue,isPrimary:'N']).call();barcodeId=result?.barcodeId

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'barcode',recordId:barcodeId,write:true]).call(); if(!access.allowed) return; def record=access.record

def prd=ec.entity.find('mantle.product.Product').condition('productId',record.productId).forUpdate(true).one()
if(!prd || prd.ownerPartyId!=record.organizationPartyId){ec.message.addError('Barcode product ownership is inconsistent.');return}
ec.service.sync().name('delete#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:barcodeId]).call()
if(record.isPrimary=='Y'){
 def next=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('productId',record.productId).condition('organizationPartyId',record.organizationPartyId).condition('isActive','Y').orderBy('barcodeId').list()
 if(next){ec.service.sync().name('update#zenith.erp.barcode.ProductBarcode').parameters([barcodeId:next[0].barcodeId,isPrimary:'Y']).call();ec.service.sync().name('update#mantle.product.Product').parameters([productId:record.productId,pseudoId:next[0].barcodeValue]).call()}
 else if(prd.pseudoId==record.barcodeValue)ec.service.sync().name('update#mantle.product.Product').parameters([productId:record.productId,pseudoId:null]).call()
}

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'product',recordId:productId,write:false]).call(); if(!access.allowed) return; def record=access.record

def rows=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',record.ownerPartyId).condition('productId',productId).condition('isActive','Y').orderBy('-isPrimary,barcodeId').list()
def primary=rows.find{it.isPrimary=='Y'}
// A disabled rich barcode must not re-enter the label pipeline through its pseudoId mirror.
def inactiveMirror=record.pseudoId && ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',record.ownerPartyId).condition('productId',productId).condition('barcodeValue',record.pseudoId).condition('isActive','N').count()
def value=primary?.barcodeValue ?: (!inactiveMirror && record.pseudoId!=productId ? record.pseudoId : null) ?: (rows ? rows[0].barcodeValue : productId)
def bc=rows.find{it.barcodeValue==value}
label=[value:value,type:bc?.barcodeTypeEnumId ?: 'BctInternal',name:record.productName ?: productId,sku:record.pseudoId ?: '',price:record.mrpAmount,owner:record.ownerPartyId]

def permission=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:'barcode']).disableAuthz().call(); if(!permission.canWrite){ec.message.addError('Barcode write access is required.');return}
def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call(); def org=scope.activeOrgId

if(!org){ec.message.addError('Select an active organization before creating a print job.');return}
if(labelId){def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'label',recordId:labelId]).call();if(!access.allowed)return;if(access.record.organizationPartyId!=org){ec.message.addError('Choose a template from the active organization.');return}}
if(!items || items.size()>500){ec.message.addError('Select between 1 and 500 product rows.');return}
def built=[:];int total=0
for(def item in items){
 def text=item.quantity?.toString()
 if(!text || !(text==~ /[0-9]{1,4}/) || text.toInteger()<1 || text.toInteger()>2000){ec.message.addError('Quantity must be a whole number from 1 to 2000.');return}
 int qty=text.toInteger();total+=qty
 if(total>2000){ec.message.addError('A print job can contain at most 2000 labels.');return}
 def product=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ProductLabel').parameters([productId:item.productId]).call()
 if(ec.message.hasError())return
 if(product.label?.owner!=org){ec.message.addError('Choose products from the print job organization.');return}
 def row=built[item.productId]
 if(row)row.quantity+=qty;else built[item.productId]=[productId:item.productId,quantity:qty,barcodeValue:product.label.value]
}
def job=ec.service.sync().name('create#zenith.erp.barcode.BarcodePrintJob').parameters([organizationPartyId:org,labelId:labelId,statusId:'BpPending',createdDate:ec.user.nowTimestamp,createdByUserId:ec.user.userId,totalLabels:total]).call();printJobId=job?.printJobId
if(ec.message.hasError())return
built.values().each{ec.service.sync().name('create#zenith.erp.barcode.BarcodePrintJobItem').parameters(it+[printJobId:printJobId,organizationPartyId:org]).call()}

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'job',recordId:printJobId,write:true]).call(); if(!access.allowed) return; def record=access.record

def job=ec.entity.find('zenith.erp.barcode.BarcodePrintJob').condition('printJobId',printJobId).forUpdate(true).one()
if(job.statusId!='BpPending'){ec.message.addError('Only pending print jobs can be edited.');return}

def text=quantity?.toString()
if(!text || !(text==~ /[0-9]{1,4}/) || text.toInteger()<1 || text.toInteger()>2000){ec.message.addError('Quantity must be a whole number from 1 to 2000.');return}
int qty=text.toInteger()
def product=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ProductLabel').parameters([productId:productId]).call()
if(ec.message.hasError())return
if(product.label?.owner!=job.organizationPartyId){ec.message.addError('Choose a product from the print job organization.');return}
def rows=ec.entity.find('zenith.erp.barcode.BarcodePrintJobItem').condition('printJobId',printJobId).list()
int total=rows.sum{it.quantity ?: 0} ?: 0
if(total+qty>2000){ec.message.addError('A print job can contain at most 2000 labels.');return}
def line=rows.find{it.productId==productId}
// Re-adding a line increments quantity without replacing the code captured when the line was created.
if(line)ec.service.sync().name('update#zenith.erp.barcode.BarcodePrintJobItem').parameters([printJobId:printJobId,productId:productId,quantity:line.quantity+qty]).call()
else ec.service.sync().name('create#zenith.erp.barcode.BarcodePrintJobItem').parameters([printJobId:printJobId,productId:productId,organizationPartyId:job.organizationPartyId,quantity:qty,barcodeValue:product.label.value]).call()
ec.service.sync().name('update#zenith.erp.barcode.BarcodePrintJob').parameters([printJobId:printJobId,totalLabels:total+qty]).call()

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'job',recordId:printJobId,write:true]).call(); if(!access.allowed) return; def record=access.record

def job=ec.entity.find('zenith.erp.barcode.BarcodePrintJob').condition('printJobId',printJobId).forUpdate(true).one()
if(job.statusId!='BpPending'){ec.message.addError('Only pending print jobs can be edited.');return}

def line=ec.entity.find('zenith.erp.barcode.BarcodePrintJobItem').condition('printJobId',printJobId).condition('productId',productId).one()
if(!line || line.organizationPartyId!=job.organizationPartyId){ec.message.addError('Print job item not found.');return}
ec.service.sync().name('delete#zenith.erp.barcode.BarcodePrintJobItem').parameters([printJobId:printJobId,productId:productId]).call()
ec.service.sync().name('zenith.barcode.BarcodeServices.recompute#PrintJobTotal').parameters([printJobId:printJobId]).call()

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'job',recordId:printJobId,write:true]).call(); if(!access.allowed) return; def record=access.record

def job=ec.entity.find('zenith.erp.barcode.BarcodePrintJob').condition('printJobId',printJobId).forUpdate(true).one()
if(job.statusId!='BpPending'){ec.message.addError('Only pending print jobs can be edited.');return}

def rows=ec.entity.find('zenith.erp.barcode.BarcodePrintJobItem').condition('printJobId',printJobId).list()
if(rows.any{it.organizationPartyId!=job.organizationPartyId}){ec.message.addError('Print job item ownership is inconsistent.');return}
ec.service.sync().name('update#zenith.erp.barcode.BarcodePrintJob').parameters([printJobId:printJobId,totalLabels:rows.sum{it.quantity ?: 0} ?: 0]).call()

def access=ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:'job',recordId:printJobId,write:true]).call(); if(!access.allowed) return; def record=access.record

def job=ec.entity.find('zenith.erp.barcode.BarcodePrintJob').condition('printJobId',printJobId).forUpdate(true).one()
if(job.statusId=='BpCompleted')return // Repeating a successful acknowledgement is a no-op.
if(!(job.statusId in ['BpPending','BpPrinting'])){ec.message.addError('This print job cannot be marked printed.');return}
def rows=ec.entity.find('zenith.erp.barcode.BarcodePrintJobItem').condition('printJobId',printJobId).list()
if(!rows || rows.any{it.organizationPartyId!=job.organizationPartyId || !it.quantity || it.quantity<1}){ec.message.addError('Add valid labels before marking this job printed.');return}
if(job.statusId=='BpPending')ec.service.sync().name('update#zenith.erp.barcode.BarcodePrintJob').parameters([printJobId:printJobId,statusId:'BpPrinting']).call()
ec.service.sync().name('update#zenith.erp.barcode.BarcodePrintJob').parameters([printJobId:printJobId,statusId:'BpCompleted',completedDate:ec.user.nowTimestamp]).call()

def permission=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:'barcode']).disableAuthz().call(); if(!permission.canWrite){ec.message.addError('Barcode write access is required.');return}
def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call(); def org=scope.activeOrgId

if(!org){ec.message.addError('Select an active organization before creating a template.');return}
def existing=[barcodeTypeEnumId:'BctCode128',columnsPerRow:3];def owner=org

def values=[:]
['labelName','labelWidth','labelHeight','columnsPerRow','barcodeTypeEnumId','showProductName','showPrice','showSku','showMrp','isDefault'].each {key -> if(context[key]!=null && context[key].toString()!='')values[key]=context[key]}
def proposed=(existing ?: [:])+values
if(!proposed.labelName?.toString()?.trim() || proposed.labelName.toString().trim().length()>255){ec.message.addError('Enter a template name of at most 255 characters.');return}
values.labelName=proposed.labelName.toString().trim()
try{
 for(def key in ['labelWidth','labelHeight']){def n=new BigDecimal(proposed[key]?.toString() ?: '');if(n<=0 || n>300)throw new IllegalArgumentException();values[key]=n}
 def n=proposed.columnsPerRow?.toString();if(!(n==~ /[0-9]{1,2}/) || n.toInteger()<1 || n.toInteger()>10)throw new IllegalArgumentException();values.columnsPerRow=n.toInteger()
}catch(Exception e){ec.message.addError('Enter positive dimensions up to 300 mm and 1–10 columns.');return}
if(!(proposed.barcodeTypeEnumId in ['BctEan13','BctEan8','BctUpcA','BctUpcE','BctCode128','BctCode39','BctQrCode','BctInternal'])){ec.message.addError('Choose a supported template barcode format.');return}
