 def n=proposed.columnsPerRow?.toString();if(!(n==~ /[0-9]{1,2}/) || n.toInteger()<1 || n.toInteger()>10)throw new IllegalArgumentException();values.columnsPerRow=n.toInteger()
}catch(Exception e){ec.message.addError('Enter positive dimensions up to 300 mm and 1–10 columns.');return}
if(!(proposed.barcodeTypeEnumId in ['BctEan13','BctEan8','BctUpcA','BctUpcE','BctCode128','BctCode39','BctQrCode','BctInternal'])){ec.message.addError('Choose a supported template barcode format.');return}
for(def key in ['showProductName','showPrice','showSku','showMrp','isDefault'])if(values.containsKey(key) && !(values[key] in ['Y','N'])){ec.message.addError('Choose Yes or No for template options.');return}
