def value=code?.toString()?.trim();if(!org || !value)return
def codes=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:value]).call().aliases
def aliases=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',org).condition('barcodeValue','in',codes).list()
def disabled=aliases.findAll{it.isActive!='Y'}.collect{it.productId} as Set
def ids=aliases.findAll{it.isActive=='Y'}.collect{it.productId} as Set
ec.entity.find('mantle.product.Product').condition('ownerPartyId',org).condition('pseudoId','in',codes).list().each{if(!disabled.contains(it.productId))ids.add(it.productId)}
