if(ids.size()>1){ambiguous=true;return}
if(ids.size()!=1)return
def product=ec.entity.find('mantle.product.Product').condition('ownerPartyId',org).condition('productId',ids.first()).one()
if(!product || product.ownerPartyId!=org ||
    (product.salesDiscontinuationDate && product.salesDiscontinuationDate <= ec.user.nowTimestamp))return
found=true;productId=product.productId

def value=(code ?: '').toString().trim();def codes=[value] as Set;def upca=null
def checked={String v -> int sum=0;for(int i=v.length()-2,j=0;i>=0;i--,j++)sum+=Character.getNumericValue(v.charAt(i))*(j%2==0?3:1);((10-sum%10)%10)==Character.getNumericValue(v.charAt(v.length()-1))}
if(value==~ /0[0-9]{12}/ && checked(value))upca=value.substring(1)
else if(value==~ /[0-9]{12}/ && checked(value))upca=value
else if(value==~ /[01][0-9]{7}/){
    def d=value.substring(1,7);def last=d[5];def expanded
    if(last in ['0','1','2'])expanded=value[0]+d.substring(0,2)+last+'0000'+d.substring(2,5)+value[7]
    else if(last=='3')expanded=value[0]+d.substring(0,3)+'00000'+d.substring(3,5)+value[7]
    else if(last=='4')expanded=value[0]+d.substring(0,4)+'00000'+d[4]+value[7]
    else expanded=value[0]+d.substring(0,5)+'0000'+last+value[7]
    if(checked(expanded))upca=expanded
}
if(upca){
    codes.add(upca);codes.add('0'+upca)
    if(upca[0] in ['0','1']){
        def manufacturer=upca.substring(1,6);def product=upca.substring(6,11);def middle=null
        if(manufacturer.substring(3)=='00' && manufacturer[2] in ['0','1','2'] && product.startsWith('00'))middle=manufacturer.substring(0,2)+product.substring(2)+manufacturer[2]
        else if(manufacturer.endsWith('00') && product.startsWith('000'))middle=manufacturer.substring(0,3)+product.substring(3)+'3'
        else if(manufacturer.endsWith('0') && product.startsWith('0000'))middle=manufacturer.substring(0,4)+product.substring(4)+'4'
        else if(product.startsWith('0000') && product[4] in ['5','6','7','8','9'])middle=manufacturer+product[4]
        if(middle)codes.add(upca[0]+middle+upca[11])
    }
}
aliases=codes as List
